def api_get_from_zeromq(params):
    def _get_socket_message(params, address, context=None, socket=None, init=False):
        if context is None:
            context = zmq.Context()
        if socket is not None and not init:
            socket.close()
            socket = context.socket(zmq.REQ)
            socket.setsockopt(zmq.LINGER, 0)
            socket.setsockopt(zmq.RCVTIMEO, 30000)
        socket.connect(address)
        socket.send_string(params)
        message = socket.recv()
        socket.close()
        context.term()
        return (message, context, socket)
    first_address = address = _get_valid_address(REPAddress)
    context = zmq.Context()
    context.setsockopt(zmq.RCVTIMEO, 30000)
    context.setsockopt(zmq.LINGER, 0)
    socket = context.socket(zmq.REQ)
    try:
        message, context, socket = _get_socket_message(params, address, context, socket, init=True)
    except BaseException:
        print('zeromq与服务端{}建立链接失败，请求数据异常'.format(address))
        _connec = False
        address = _get_valid_address(REPAddress, _next_address=True)
        while first_address != address:
            try:
                message, context, socket = _get_socket_message(params, address, context, socket)
                _connec = True
            except Exception as e:
                print('zeromq与服务端{}建立链接失败，请求数据异常'.format(address))
                print('zeromq与服务端建立链接失败，请求数据异常, 异常:{}'.format(e))
                address = _get_valid_address(REPAddress, _next_address=True)
