def build_future_fill_time(suffix, typet, start, end):
    all_days = pd.date_range(start=start[:8], end=end[:8], freq='B')
    holidays = data_proxy().get_holiday_local()
    trade_days = []
    for item in all_days:
        if item.strftime('%Y%m%d') not in holidays:
            trade_days.append(item.strftime('%Y-%m-%d'))
    total_dts = []
    if not typet == 5:
        if typet == 1:
            tmp = MarketTime.get_instance().get_market_time(suffix)
            open_am = tmp['open_am'][:2] + ':' + tmp['open_am'][-2:] + ':00'
            close_am = tmp['close_am'][:2] + ':' + tmp['close_am'][-2:] + ':00'
            open_pm = tmp['open_pm'][:2] + ':' + tmp['open_pm'][-2:] + ':00'
            close_pm = tmp['close_pm'][:2] + ':' + tmp['close_pm'][-2:] + ':00'
            maket_time = {'open_am': open_am, 'close_am': close_am, 'open_pm': open_pm, 'close_pm': close_pm, 'freq': 'T'}
            out_trade_times = pd.date_range(start=maket_time['close_am'], end=maket_time['open_pm'], freq=maket_time['freq'])[1:-1]
            trade_times = pd.date_range(start=maket_time['open_am'], end=maket_time['close_pm'], freq=maket_time['freq'])
            trade_times = trade_times[~numpy.in1d(trade_times, out_trade_times)]
            trade_times = [item.strftime(' %H:%M:%S') for item in trade_times]
            for today in trade_days:
                for item in trade_times:
                    total_dts.append(today + item)
        elif typet == 2:
            if suffix == 'T.CCFX':
                maket_time = {'open_am': ' 09:20:00', 'close_am': ' 11:30:00', 'open_pm': ' 13:05:00', 'close_pm': ' 15:15:00', 'freq': '5T'}
            else:
                maket_time = {'open_am': ' 09:05:00', 'close_am': ' 11:30:00', 'open_pm': ' 13:35:00', 'close_pm': ' 15:00:00', 'freq': '5T'}
            dt_am = pd.date_range(start=maket_time['open_am'], end=maket_time['close_am'], freq=maket_time['freq'])
            dt_pm = pd.date_range(start=maket_time['open_pm'], end=maket_time['close_pm'], freq=maket_time['freq'])
            trade_times = dt_am.append(dt_pm)
            trade_times = [item.strftime(' %H:%M:%S') for item in trade_times]
            for today in trade_days:
                for item in trade_times:
                    total_dts.append(today + item)
        elif typet == 3:
            if suffix == 'T.CCFX':
                maket_time = {'open_am': ' 09:30:00', 'close_am': ' 11:30:00', 'open_pm': ' 13:15:00', 'close_pm': ' 15:15:00', 'freq': '15T'}
            else:
                maket_time = {'open_am': ' 09:15:00', 'close_am': ' 11:30:00', 'open_pm': ' 13:45:00', 'close_pm': ' 15:00:00', 'freq': '15T'}
            dt_am = pd.date_range(start=maket_time['open_am'], end=maket_time['close_am'], freq=maket_time['freq'])
            dt_pm = pd.date_range(start=maket_time['open_pm'], end=maket_time['close_pm'], freq=maket_time['freq'])
            trade_times = dt_am.append(dt_pm)
            trade_times = [item.strftime(' %H:%M:%S') for item in trade_times]
            for today in trade_days:
                for item in trade_times:
                    total_dts.append(today + item)
        elif typet == 4:
            if suffix == 'T.CCFX':
                maket_time = {' 13:15:00', ' 10:45:00', ' 14:15:00', ' 15:15:00', ' 10:15:00', ' 13:45:00', ' 09:45:00', ' 11:15:00', ' 14:45:00'}
            else:
                maket_time = {' 10:45:00', ' 09:30:00', ' 10:00:00', ' 14:15:00', ' 13:45:00', ' 11:15:00', ' 15:00:00', ' 14:45:00'}
            for today in trade_days:
                for item in maket_time:
                    total_dts.append(today + item)
    else:
        if suffix == 'T.CCFX':
            maket_time = [' 10:15:00', ' 11:15:00', ' 13:45:00', ' 14:45:00', ' 15:15:00']
        else:
            maket_time = [' 10:00:00', ' 11:15:00', ' 14:15:00', ' 15:00:00']
        for today in trade_days:
            for item in maket_time:
                total_dts.append(today + item)
    if total_dts:
        total_dts = pd.to_datetime(total_dts)
    else:
        total_dts = pd.to_datetime([])
    return total_dts
